// /annotation/semantic_segments message (Protobuf schema from docs.lightwheel.net)
message SemanticSegment {
  common.header.Header header = 1;
  string task_description = 2;   // episode-level, same for all segments
  SegmentInfo segment = 3;
}
message SegmentInfo {
  string subtask_description = 1;
  repeated string skill = 2;
  double start_time = 3;
  double end_time = 4;
}
